import settings


def bind(config=None):
    options = settings.load() if config is None else config
    return ("127.0.0.1", options["port"])

pkg/urls.py:
from pkg.net import localhost


def describe(endpoint, tls):
    host, port = endpoint
    scheme = "https" if tls else "http"
    return {"public_url": f"{scheme}://{host}:{port}", "diagnostic_url": f"http://{localhost()}:{port}/status"}

